    {
      "instrument_id": "EQ18",
      "role": "primary",
      "technique": "Differential Scanning Calorimetry (DSC)",
      "why": "DSC measures heat flow changes associated with thermal transitions, providing a direct and accurate determination of the glass transition temperature (Tg) crucial for storage stability predictions.",
      "accessories_to_confirm": [
        "Standard DSC aluminum pans and lids",
        "Purge gas supply (nitrogen)",
        "Chilled cooling accessory"
      ]
    },
    {
      "instrument_id": "EQ17",
      "role": "supplementary",
      "technique": "Thermogravimetric Analysis (TGA)",
      "why": "TGA measures mass change as a function of temperature, helping verify that thermal transitions observed by DSC are not confounded by solvent evaporation or thermal degradation.",
      "accessories_to_confirm": [
        "Platinum sample pans",
        "Purge gas supply"
      ]
    },
    {
      "instrument_id": "EQ19",
      "role": "supplementary",
      "technique": "Dynamic Mechanical Analysis / Rheology Temperature Sweep",
      "why": "Rheological temperature sweeps can also detect the glass transition via changes in viscoelastic moduli (storage and loss moduli), serving as a complementary method to DSC.",
      "accessories_to_confirm": [
        "Specific upper and lower test fixtures (e.g., parallel plate or solid support fixtures)",
        "Temperature control system"
      ]
